  const ydoc = TiptapTransformer.toYdoc(json, 'default', extensions)
  roundTrip = TiptapTransformer.fromYdoc(ydoc, 'default')
} catch (e) {
  threw = e.message
}
const unknown = {
  type: 'doc',
  content: [
