}
let unknownThrew = null
try {
  TiptapTransformer.toYdoc(unknown, 'default', extensions)
} catch (e) {
  unknownThrew = e.message.split('\n')[0]
}
console.log(JSON.stringify({ threw, roundTrip, unknownThrew }, null, 2))
